  async function review(decision:'approve'|'return'){if(!course)return;if(decision==='return'&&!feedback.trim()){notify('Feedback is required when returning results.','error');return;}setBusy(true);try{await post(`/api/courses/${course.id}/review`,{decision,feedback});notify(decision==='approve'?'Results approved and published.':'Results returned to the lecturer.');setCourse(null);load();onRefresh();}catch(e){notify(errorText(e),'error');}finally{setBusy(false);}}
